def compute(vars):
    hard_assets = vars["v1"]
    net_assets_acquired = vars["v2"]

    if net_assets_acquired == 0:
        return None

    ratio = hard_assets / net_assets_acquired
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "hard_assets": hard_assets,
            "net_assets_acquired": net_assets_acquired,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
